import csv
import io
import re
from typing import List, Dict, Any, Optional

def parse_csv(raw_csv: str):
    if raw_csv is None:
        return {"columns": [], "rows": []}

    text = raw_csv.replace("\r\n", "\n").replace("\r", "\n")
    lines = text.split("\n")

    def is_blank(s: str) -> bool:
        return s.strip() == ""

    def count_delims_outside_quotes(s: str, delim: str = ",", quote: str = '"') -> int:
        in_q = False
        i = 0
        c = 0
        while i < len(s):
            ch = s[i]
            if ch == quote:
                if in_q and i + 1 < len(s) and s[i + 1] == quote:
                    i += 2
                    continue
                in_q = not in_q
            elif ch == delim and not in_q:
                c += 1
            i += 1
        return c

    def parse_record(record: str) -> List[str]:
        reader = csv.reader(io.StringIO(record), delimiter=",", quotechar='"', doublequote=True, skipinitialspace=False)
        try:
            return next(reader)
        except StopIteration:
            return []

    def join_physical_lines(start_idx: int) -> (str, int):
        buf = []
        in_q = False
        i = start_idx
        while i < len(lines):
            line = lines[i]
            buf.append(line)
            j = 0
            while j < len(line):
                ch = line[j]
                if ch == '"':
                    if in_q and j + 1 < len(line) and line[j + 1] == '"':
                        j += 2
                        continue
                    in_q = not in_q
                j += 1
            if not in_q:
                return "\n".join(buf), i + 1
            i += 1
        return "\n".join(buf), len(lines)

    records = []
    i = 0
    while i < len(lines):
        if is_blank(lines[i]):
            i += 1
            continue
        rec, ni = join_physical_lines(i)
        if rec.strip() != "":
            records.append(rec)
        i = ni

    if not records:
        return {"columns": [], "rows": []}

    header_rows = 3
    header_records = records[:header_rows] if len(records) >= header_rows else records[:]
    data_records = records[header_rows:] if len(records) > header_rows else []

    header_parts = [parse_record(r) for r in header_records]
    maxw = max((len(p) for p in header_parts), default=0)

    columns = []
    for idx in range(maxw):
        vals = []
        for row in header_parts:
            if idx < len(row):
                v = row[idx].strip()
                if v:
                    vals.append(v)
        col = " ".join(vals).strip()
        columns.append(col if col else f"column_{idx+1}")

    rows = []
    expected_width = max(9, len(columns))
    for rec in data_records:
        row = parse_record(rec)
        if len(row) < expected_width:
            row = row + [""] * (expected_width - len(row))
        elif len(row) > expected_width:
            row = row[:expected_width - 1] + [",".join(row[expected_width - 1:])]
        rows.append([str(v) for v in row])

    if len(columns) < expected_width:
        columns.extend([f"column_{i+1}" for i in range(len(columns), expected_width)])

    return {"columns": columns, "rows": rows}
